-- Meta Ads (somente leitura): gasto por dia da conta e desempenho por anúncio no mês.
CREATE TABLE IF NOT EXISTS ads_diario(conta VARCHAR(64) NOT NULL,dia VARCHAR(10) NOT NULL,gasto DECIMAL(14,2) NOT NULL DEFAULT 0,impressoes BIGINT NOT NULL DEFAULT 0,cliques BIGINT NOT NULL DEFAULT 0,resultados BIGINT NOT NULL DEFAULT 0,moeda VARCHAR(8) NOT NULL DEFAULT '',atualizado_em VARCHAR(40) NOT NULL,PRIMARY KEY(conta,dia)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ads_anuncios(conta VARCHAR(64) NOT NULL,anuncio_id VARCHAR(64) NOT NULL,periodo VARCHAR(10) NOT NULL,anuncio VARCHAR(250) NOT NULL DEFAULT '',campanha VARCHAR(200) NOT NULL DEFAULT '',gasto DECIMAL(14,2) NOT NULL DEFAULT 0,impressoes BIGINT NOT NULL DEFAULT 0,alcance BIGINT NOT NULL DEFAULT 0,cliques BIGINT NOT NULL DEFAULT 0,resultados BIGINT NOT NULL DEFAULT 0,moeda VARCHAR(8) NOT NULL DEFAULT '',status VARCHAR(40) NOT NULL DEFAULT '',problema VARCHAR(500) NOT NULL DEFAULT '',atualizado_em VARCHAR(40) NOT NULL,PRIMARY KEY(conta,anuncio_id,periodo)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
